import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"qrcode Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"qrcode","tag":"qrcode","title":"qrcode Tag","prev":null,"next":null,"posts":[{"title":"QR code 生成的相关参数","url":"/posts/2023-03-03-qrcode-version/","date":"2023-03-03 20:42","tags":["qrcode"],"html":"<p>QR code 本身就是把文字生成一个二维码的过程，顶多指定一下纠错等级。但是有些硬件设备只支持特定参数的二维码，所以我就查了一下二维码的相关规范了解一下生成过程中需要哪些参数。</p>\\n<h2 id=\\"version\\" tabindex=\\"-1\\">version <a class=\\"header-anchor\\" href=\\"#version\\" aria-label=\\"Permalink to &quot;version&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>二维码有一个 version 参数，范围是从 1 到 40。 每个版本都具备固有的码元结构(码元数)，码元是指构成 QR 码的方形黑白点。“码元结构”是指二维码中的码元数。从版本 1(21 码元 ×21 码元)开始，在纵向和横向各自以 4 码元为单位递增，一直到版本 40(177 码元 ×177 码元)。规律是 4n +17 (n 代表版本号)。版本越大能容纳的信息就越多，一般是选择能容纳所需信息的最小版本即可。</p>\\n<h2 id=\\"error-correction-level\\" tabindex=\\"-1\\">error correction level <a class=\\"header-anchor\\" href=\\"#error-correction-level\\" aria-label=\\"Permalink to &quot;error correction level&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>QR 码具有纠错功能，保证二维码在丢失一定数据的情况下还是可以读取。纠错有四个级别分别是：</p>\\n<ol>\\n<li>L (Low) 纠错 7%</li>\\n<li>M (Medium) 纠错 15%</li>\\n<li>Q (Quartile) 纠错 25%</li>\\n<li>H (High) 纠错 30%</li>\\n</ol>\\n<p>纠错能力越高需要存储的信息就越多，对应需要的 version 就要越高。</p>\\n<h2 id=\\"mask\\" tabindex=\\"-1\\">mask <a class=\\"header-anchor\\" href=\\"#mask\\" aria-label=\\"Permalink to &quot;mask&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>mask 是为了防止二维码有大量空白或者填充，让扫描器尽可能容易的进行扫描。mask 方案目前有 8 种。</p>\\n<p><img src=\\"https://upload.wikimedia.org/wikipedia/commons/c/c8/QR_Code_Mask_Patterns.svg\\" alt=\\"Mask Pattern\\" loading=\\"lazy\\"></p>\\n<p>选择 mask 的方案有相关的标准可以自行查询，本质目标是让生成的图片尽量黑白相间，避免同一颜色的色块大量出现，方便扫描器读取数据。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>普通业务使用的二维码相关库应该只提供文本接口和纠错标准的设定，会根据文本长度和纠错标准来自动其他两个参数。但是针对特殊需求的情况下就需要把 version 和 mask 参数暴露出来。\\n同时因为手动指定 version 也会因为 version 版本太低导致无法生成合法的二维码的情况。使用的时候需要注意。我本身有修改一个版本可以传入底层参数，可以看一下参考链接。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://www.qrcode.com/en/about/version.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Information capacity and versions of QR Code</a></p>\\n<p><a href=\\"https://www.keyence.com/ss/products/auto_id/codereader/basic_2d/qr.jsp\\" target=\\"_blank\\" rel=\\"noreferrer\\">What is a QR code?</a></p>\\n<p><a href=\\"https://github.com/nayuki/QR-Code-generator\\" target=\\"_blank\\" rel=\\"noreferrer\\">QR Code generator</a></p>\\n<p><a href=\\"https://en.wikiversity.org/wiki/Reed%E2%80%93Solomon_codes_for_coders\\" target=\\"_blank\\" rel=\\"noreferrer\\">Reed–Solomon codes for coders</a></p>\\n<p><a href=\\"https://github.com/acgotaku/simple-qr-reader/blob/master/src/vendors/qrcode/qrcodegen.ts\\" target=\\"_blank\\" rel=\\"noreferrer\\">qrcodegen</a></p>\\n"},{"title":"网页调用摄像头读取QR code","url":"/posts/2022-12-17-web-qr-reader/","date":"2022-12-17 17:29","tags":["qrcode"],"html":"<p>2022 年也要结束了，博客不能停更。最近项目中有读取 QR 码的需求，于是便调研了下如何实现这个功能，顺便写篇博客记录下。</p>\\n<h2 id=\\"现成-react-框架\\" tabindex=\\"-1\\">现成 React 框架 <a class=\\"header-anchor\\" href=\\"#现成-react-框架\\" aria-label=\\"Permalink to &quot;现成 React 框架&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先调研了别人封装好的现成框架，<a href=\\"https://github.com/react-qr-reader/react-qr-reader\\" target=\\"_blank\\" rel=\\"noreferrer\\">React QR Reader</a>。这个框架看起来还挺流行的，可是最新版本的发布已经是 2019 年了。\\n而且有一个致命的 BUG 就是在开启摄像头之后无法关闭。必须重新刷新页面才行，这是不能接受的。</p>\\n<h2 id=\\"低层封装框架\\" tabindex=\\"-1\\">低层封装框架 <a class=\\"header-anchor\\" href=\\"#低层封装框架\\" aria-label=\\"Permalink to &quot;低层封装框架&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>发现大家基本都是调用<a href=\\"https://github.com/zxing-js/browser\\" target=\\"_blank\\" rel=\\"noreferrer\\">@zxing/browser</a>来完成核心功能的。于是我也使用这个框架封装一个不就好了。\\n首先安装相关依赖：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">pnpm</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> @zxing/browser</span><span style=\\"color:#032F62\\"> @zxing/library</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>具体的封装代码如下：</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> QrReader</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">FC</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">IQrReaderProps</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> ({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  videoId </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'video'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  scanDelay </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 500</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  constraints </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    facingMode: </span><span style=\\"color:#032F62\\">'environment'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  className </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> ''</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  onResult</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> stopRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">false</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> videoRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLVideoElement</span><span style=\\"color:#D73A49\\"> |</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">>(</span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  useEffect</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (videoRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      const</span><span style=\\"color:#005CC5\\"> codeReader</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> BrowserQRCodeReader</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">undefined</span><span style=\\"color:#24292E\\">, {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        delayBetweenScanAttempts: scanDelay</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      stopRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      codeReader</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        .</span><span style=\\"color:#6F42C1\\">decodeFromConstraints</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            video: constraints</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          videoRef.current,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          (</span><span style=\\"color:#E36209\\">result</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">error</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">controls</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            onResult </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#6F42C1\\"> onResult</span><span style=\\"color:#24292E\\">(result, error, controls);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            if</span><span style=\\"color:#24292E\\"> (stopRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              controls.</span><span style=\\"color:#6F42C1\\">stop</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        )</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        .</span><span style=\\"color:#6F42C1\\">catch</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">error</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          onResult </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#6F42C1\\"> onResult</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">undefined</span><span style=\\"color:#24292E\\">, error);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      stopRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, [videoId, scanDelay, constraints, onResult]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;</span><span style=\\"color:#22863A\\">section</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{</span><span style=\\"color:#6F42C1\\">cls</span><span style=\\"color:#24292E\\">(styles.reader, className)}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{styles.container}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;</span><span style=\\"color:#005CC5\\">ViewFinder</span><span style=\\"color:#24292E\\"> /></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;</span><span style=\\"color:#22863A\\">video</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          muted</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          ref</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{videoRef}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{styles.video}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          style</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            transform:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              constraints?.facingMode </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'user'</span><span style=\\"color:#D73A49\\"> ?</span><span style=\\"color:#032F62\\"> 'scaleX(-1)'</span><span style=\\"color:#D73A49\\"> :</span><span style=\\"color:#032F62\\"> 'none'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        /></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;/</span><span style=\\"color:#22863A\\">section</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br></div></div><p>这里使用了 <code>stopRef</code> 来标记组件的销毁并停止调用摄像头。本身封装也不复杂，没必要使用别人封装的轮子。完整的代码在<a href=\\"https://github.com/acgotaku/simple-qr-reader\\" target=\\"_blank\\" rel=\\"noreferrer\\">simple-qr-reader</a></p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前端生态非常完善，使用现成的库就可以非常方便的实现调用摄像头读取二维码功能。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://zenn.dev/terrierscript/articles/2020-12-22-zxing-browser-react-qr-code-reader\\" target=\\"_blank\\" rel=\\"noreferrer\\">@zxing/browser と React の組み合わせで QR Code Reader 作る</a></p>\\n"}]},"relativePath":"tags/qrcode/index.md","filePath":"tags/[slug].md"}`),e={name:"tags/qrcode/index.md"};function l(p,r,o,c,t,i){return n(),a("div")}const d=s(e,[["render",l]]);export{b as __pageData,d as default};
